create extension if not exists pgcrypto;

create or replace function public.fir_saathi_set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$;

create table if not exists public.fir_saathi_complaints (
  id uuid primary key default gen_random_uuid(),
  public_id text not null unique,
  language text not null check (language in ('en', 'hi', 'gu')),
  status text not null default 'draft' check (status in ('draft', 'needs_citizen_confirmation', 'ready_for_review', 'returned', 'verified')),
  consent_at timestamptz,
  citizen_confirmed_at timestamptz,
  source_transcript text not null,
  draft_json jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.fir_saathi_complaint_fields (
  id uuid primary key default gen_random_uuid(),
  complaint_id uuid not null references public.fir_saathi_complaints(id) on delete cascade,
  field_key text not null,
  label text not null,
  value text not null,
  source text not null check (source in ('source_statement', 'assistant_draft', 'officer_correction')),
  confidence text not null check (confidence in ('high', 'medium', 'low', 'manual')),
  verification_state text not null default 'unverified' check (verification_state in ('unverified', 'citizen_confirmed', 'officer_verified')),
  updated_at timestamptz not null default now(),
  unique (complaint_id, field_key)
);

create table if not exists public.fir_saathi_audio_evidence (
  id uuid primary key default gen_random_uuid(),
  complaint_id uuid not null references public.fir_saathi_complaints(id) on delete cascade,
  storage_key text,
  mime_type text,
  byte_size integer check (byte_size is null or byte_size >= 0),
  sha256 text check (sha256 is null or sha256 ~ '^[a-f0-9]{64}$'),
  encryption_metadata jsonb,
  tamper_status text not null default 'not_checked' check (tamper_status in ('not_checked', 'match', 'mismatch', 'unavailable')),
  created_at timestamptz not null default now()
);

create table if not exists public.fir_saathi_audit_events (
  id uuid primary key default gen_random_uuid(),
  complaint_id uuid not null references public.fir_saathi_complaints(id) on delete cascade,
  actor_label text not null,
  actor_role text not null check (actor_role in ('citizen', 'constable', 'system')),
  event_type text not null check (event_type in ('created', 'transcribed', 'drafted', 'citizen_confirmed', 'field_corrected', 'returned', 'verified', 'evidence_checked')),
  field_key text,
  previous_value text,
  new_value text,
  reason text,
  created_at timestamptz not null default now()
);

create table if not exists public.fir_saathi_bns_references (
  id uuid primary key default gen_random_uuid(),
  section_code text not null unique,
  title text not null,
  summary text not null,
  source_label text not null,
  verification_status text not null default 'demo_only' check (verification_status in ('demo_only', 'unverified', 'verified')),
  updated_at timestamptz not null default now()
);

create index if not exists fir_saathi_complaints_status_idx on public.fir_saathi_complaints(status);
create index if not exists fir_saathi_complaints_created_idx on public.fir_saathi_complaints(created_at desc);
create index if not exists fir_saathi_fields_complaint_idx on public.fir_saathi_complaint_fields(complaint_id);
create index if not exists fir_saathi_audio_complaint_idx on public.fir_saathi_audio_evidence(complaint_id);
create index if not exists fir_saathi_audit_complaint_created_idx on public.fir_saathi_audit_events(complaint_id, created_at desc);

drop trigger if exists fir_saathi_complaints_updated_at on public.fir_saathi_complaints;
create trigger fir_saathi_complaints_updated_at before update on public.fir_saathi_complaints for each row execute function public.fir_saathi_set_updated_at();
drop trigger if exists fir_saathi_fields_updated_at on public.fir_saathi_complaint_fields;
create trigger fir_saathi_fields_updated_at before update on public.fir_saathi_complaint_fields for each row execute function public.fir_saathi_set_updated_at();
drop trigger if exists fir_saathi_bns_updated_at on public.fir_saathi_bns_references;
create trigger fir_saathi_bns_updated_at before update on public.fir_saathi_bns_references for each row execute function public.fir_saathi_set_updated_at();

alter table public.fir_saathi_complaints enable row level security;
alter table public.fir_saathi_complaint_fields enable row level security;
alter table public.fir_saathi_audio_evidence enable row level security;
alter table public.fir_saathi_audit_events enable row level security;
alter table public.fir_saathi_bns_references enable row level security;

drop policy if exists fir_saathi_complaints_service_role on public.fir_saathi_complaints;
create policy fir_saathi_complaints_service_role on public.fir_saathi_complaints for all to service_role using (true) with check (true);
drop policy if exists fir_saathi_fields_service_role on public.fir_saathi_complaint_fields;
create policy fir_saathi_fields_service_role on public.fir_saathi_complaint_fields for all to service_role using (true) with check (true);
drop policy if exists fir_saathi_audio_service_role on public.fir_saathi_audio_evidence;
create policy fir_saathi_audio_service_role on public.fir_saathi_audio_evidence for all to service_role using (true) with check (true);
drop policy if exists fir_saathi_audit_service_role on public.fir_saathi_audit_events;
create policy fir_saathi_audit_service_role on public.fir_saathi_audit_events for all to service_role using (true) with check (true);
drop policy if exists fir_saathi_bns_service_role on public.fir_saathi_bns_references;
create policy fir_saathi_bns_service_role on public.fir_saathi_bns_references for all to service_role using (true) with check (true);
